# Bin Packing Example
# Capacity C = 10
# Items in arrival order
items = [5, 5, 5, 3, 3, 3, 7, 7]
C = 10

def first_fit(items, cap):
    bins = []
    for w in items:
        placed = False
        for b in bins:
            if sum(b) + w <= cap:
                b.append(w)
                placed = True
                break
        if not placed:
            bins.append([w])
    return bins

def optimal_packing(items, cap):
    # Simple exhaustive search for this small instance
    best = None
    from itertools import product
    # assign each item to a bin index; try up to len(items) bins
    n = len(items)
    for k in range(1, n+1):
        # generate assignments using numbers 0..k-1
        for assign in product(range(k), repeat=n):
            bins = [[] for _ in range(k)]
            ok = True
            for w, idx in zip(items, assign):
                bins[idx].append(w)
            for b in bins:
                if sum(b) > cap:
                    ok = False
                    break
            if ok:
                # remove empty bins
                used = [b for b in bins if b]
                if best is None or len(used) < len(best):
                    best = used
                if len(best) == 1:
                    return best
        if best is not None:
            return best
    return best

ff_bins = first_fit(items, C)
opt_bins = optimal_packing(items, C)

def format_bins(bins):
    return [list(b) for b in bins]

print('First Fit packing:', format_bins(ff_bins))
print('Optimal packing   :', format_bins(opt_bins))
print('Gap (bins):', len(ff_bins) - len(opt_bins))

# Self‑test
assert sum(len(b) for b in ff_bins) == len(items)
assert sum(len(b) for b in opt_bins) == len(items)
for b in ff_bins + opt_bins:
    assert sum(b) <= C
print('Self‑test passed')

# Witness output
import json
witness = {
    "polarity": "positive",
    "evidence": {"path": "execution://witness"},
    "data": {
        "first_fit_bins": ff_bins,
        "optimal_bins": opt_bins,
        "gap": len(ff_bins) - len(opt_bins)
    }
}
print('WITNESS:', json.dumps(witness))

import itertools, json, sys

def first_fit(items, capacity=10):
    bins=[]
    for item in items:
        placed=False
        for b in bins:
            if sum(b)+item<=capacity:
                b.append(item)
                placed=True
                break
        if not placed:
            bins.append([item])
    return bins

def optimal_packing(items, capacity=10):
    # simple exhaustive search using recursion, suitable for small list
    best=None
    def backtrack(remaining, current_bins):
        nonlocal best
        if not remaining:
            if best is None or len(current_bins)<len(best):
                best=[list(b) for b in current_bins]
            return
        if best is not None and len(current_bins)>=len(best):
            return
        item=remaining[0]
        for i,bin_ in enumerate(current_bins):
            if sum(bin_)+item<=capacity:
                current_bins[i].append(item)
                backtrack(remaining[1:], current_bins)
                current_bins[i].pop()
        # new bin
        current_bins.append([item])
        backtrack(remaining[1:], current_bins)
        current_bins.pop()
    backtrack(list(items),[])
    return best

def validate(packing, items, capacity=10):
    flat=[i for bin_ in packing for i in bin_]
    assert sorted(flat)==sorted(items), "Item mismatch"
    for bin_ in packing:
        assert sum(bin_)<=capacity, "Capacity exceeded"

items=[5,5,5,3,3,3,7,7]
ff=first_fit(items)
opt=optimal_packing(items)
validate(ff,items)
validate(opt,items)
gap=len(ff)-len(opt)
result={"first_fit":ff,"optimal":opt,"gap":gap}
print("WITNESS: "+json.dumps({"polarity":"positive","evidence":{"path":"execution://witness"},"data":result}))

